window.bookSummaryJSON = "<p><b>The seas spell freedom.</b><br> <br> Pirates and kraken, boats and submarines, deadly sirens, mermaids, and the women who face them all. These are our heroes.<br> <br> High seas adventure, fantasy, and magic weave together in this sapphic anthology focusing on the joy of the unbounded oceans.<br> <br> If you like diverse stories with lesbian and sapphic heroines exploring oceans, battling sea monsters, and seducing pirates, buy <i>Farther Reefs</i> today!</p>"; 
